import re
T=re.compile(r'^(kb|coord|sessions|querylog|host|sprint|log)  (ok|timeout|error|absent|unsupported)  \d+\.\ds(  — .+)?$')
H=re.compile(r'^kbmon · \d{4}-\d\d-\d\d \d\d:\d\d:\d\dZ · refresh \d+s · frame \d+ · \S+$')
for cols in (80,120):
    E=dict(os.environ,COLUMNS=str(cols),LINES='60',NO_COLOR='1');p=k('--once',env=E)
    if p.returncode not in (0,1): fail('--once exit %s: %s'%(p.returncode,p.stderr[-300:]))
    L=p.stdout.splitlines()
    over=[x for x in L if len(x)>cols-1]
    if over: fail('%d lines past W=%d, first %r'%(len(over),cols-1,over[0][:60]))
    i=2 if L and L[0].startswith('!! ALERT') else 0
    if len(L)<=i or not H.match(L[i]): fail('header %r'%(L[i] if len(L)>i else None))
    titles=[m[1] for x in L if (m:=T.match(x))]
    if titles!=['kb','coord','sessions','querylog','host','sprint','log']: fail('panel titles %r'%titles)
    bad=[x for x in L[i+1:] if x and not T.match(x) and x[:2] not in ('  ','! ','!!')]
    if bad: fail('a body row without its gutter: %r'%bad[0][:60])
print('ok: header, seven panel titles in order, gutters, no line past W at 80 and 120 columns')
